export const stations=['S1','S2'];
export function estimate(r,method){return r.sign!=='<'?r.value:method==='exclude'?null:method==='zero'?0:method==='limit'?r.value:r.value/2;}
export function select(records,state){return records.filter(r=>r.param===state.param&&(state.year==='all'||r.date.startsWith(state.year))&&state.stations.includes(r.station));}
export function summarized(rows,method){const values=rows.map(r=>estimate(r,method)).filter(v=>v!==null);const sorted=[...values].sort((a,b)=>a-b);return {count:rows.length,used:values.length,below:rows.filter(r=>r.sign==='<').length,mean:values.length?values.reduce((a,b)=>a+b,0)/values.length:null,max:values.length?Math.max(...values):null,min:values.length?Math.min(...values):null,median:values.length?(sorted[Math.floor((sorted.length-1)/2)]+sorted[Math.floor(sorted.length/2)])/2:null};}
export function unitFor(param,records){return ['COD','BOD5'].includes(param)?'mg/L (O₂)':records.find(r=>r.param===param)?.unit||'—';}
// 'out' fuori soglia, 'ok' entro soglia, 'na' non valutabile (valore «<» con LOQ oltre la soglia), null se la soglia non è numerica.
export function assess(r,t){if(t?.min==null&&t?.max==null)return null;const v=r.value;if(r.sign==='<'){if(t.min!=null&&v<=t.min)return 'out';return t.min!=null||(t.max!=null&&v>t.max)?'na':'ok';}return (t.min!=null&&v<t.min)||(t.max!=null&&v>t.max)?'out':'ok';}
export function compliance(rows,t){const c={out:0,ok:0,na:0,assessed:0};if(t?.min==null&&t?.max==null)return null;rows.forEach(r=>{const a=assess(r,t);c[a]++;if(a!=='na')c.assessed++;});return c;}
export const assessNames={out:'Fuori soglia',ok:'Entro soglia',na:'Non valutabile'};
export function thresholdText(t){return t?t.label+(t.converted?' → '+t.converted:''):'';}
export function csv(rows,method,thresholds={}){const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';const head=['Campione','Data e ora originali','Parametro','Stazione','Codice stazione','Segno','Valore originale','Unità originale','Valore elaborato','Metodo','Fonte','Riga','Parametro nel file','Valore soglia','Confronto con la soglia'];return '﻿'+[head,...rows.map(r=>{const t=thresholds[r.param];return [r.sample,r.timestamp,r.param,r.station,r.code,r.sign,r.value,r.unit,estimate(r,method),method,r.source,r.row,r.original,thresholdText(t),assessNames[assess(r,t)]];})].map(r=>r.map(quote).join(';')).join('\r\n');}
